    "         {ifname:\"vtnet0\",driver:\"virtio-net\",mac:\"unknown\",pci:\"00:04.0\",active:false,link:false,role:\"lan\"}]},\n"
    " lan:{ip:\"192.168.10.1\",mask:\"255.255.255.0\",dhcp:{enabled:true,pool_start:\"192.168.10.100\",pool_end:\"192.168.10.200\",lease:3600,\n"
    "  leases:[{ip:\"192.168.10.101\",mac:\"3c:22:fb:8a:11:9e\",host:\"laptop\",bound:true,expires:2871},{ip:\"192.168.10.102\",mac:\"a4:5e:60:d1:77:02\",host:\"phone\",bound:true,expires:1902},{ip:\"192.168.10.103\",mac:\"00:1b:44:11:3a:b8\",host:\"\",bound:false,expires:41}],\n"
    "  reservations:[{id:1,ip:\"192.168.10.10\",mac:\"b8:27:eb:4f:2a:11\",host:\"nas\"}]}},\n"
    " wan:{mode:\"dhcp\",status:\"dhcp bound 10.0.2.15\",ip:\"10.0.2.15\",mask:\"255.255.255.0\",gw:\"10.0.2.2\",dns:\"10.0.2.3\",link:true,dhcp_state:\"bound 10.0.2.15\",lease_left:2700},\n"
    " dns:{enabled:true,upstream:\"10.0.2.3\",secondary:\"8.8.8.8\",domain:\"lan\",records:[{name:\"nas.lan\",ip:\"192.168.10.10\",local:true},{name:\"example.com\",ip:\"93.184.216.34\",local:false}]},\n"
    " nat:{enabled:true,forwards:[{id:1,proto:\"tcp\",wan_port:8080,lan_port:80,lan_ip:\"192.168.10.10\",hits:12,comment:\"nas web\"}],mappings:[{proto:6,lan_ip:\"192.168.10.101\",lan_port:52144,wan_port:30142,remote_ip:\"93.184.216.34\",packets:38}]},\n"
    " http:{port:69,running:true,auth:true},\n"
    " stats:{dhcp_discover:14,dhcp_offer:14,dhcp_request:9,dhcp_ack:9,dhcp_nak:0,dns_queries:203,dns_local:44,dns_forwarded:151,dns_cached:88,dns_failed:2,nat_mappings:37,forwarded_frames:1842,dropped_frames:6,http_requests:28},\n"
    " firewall:{in:\"deny\",out:\"allow\",forward:\"deny\",rate:0,rules:[\n"
    "  {id:1,action:\"allow\",protocol:\"any\",dir:\"any\",enabled:true,src:\"any\",dst:\"any\",dport:0,dport_end:65535,sport:0,state:2,log:false,hits:1821,comment:\"established\"},\n"
    "  {id:2,action:\"allow\",protocol:\"any\",dir:\"forward\",enabled:true,src:\"192.168.10.0/24\",dst:\"any\",dport:0,dport_end:65535,sport:0,state:0,log:false,hits:921,comment:\"lan to wan\"},\n"
    "  {id:3,action:\"allow\",protocol:\"any\",dir:\"in\",enabled:true,src:\"192.168.10.0/24\",dst:\"any\",dport:0,dport_end:65535,sport:0,state:0,log:false,hits:203,comment:\"lan to router\"},\n"
    "  {id:4,action:\"deny\",protocol:\"udp\",dir:\"in\",enabled:true,src:\"any\",dst:\"any\",dport:67,dport_end:67,sport:0,state:0,log:false,hits:6,comment:\"wan dhcp blocked\"},\n"
    "  {id:5,action:\"deny\",protocol:\"udp\",dir:\"in\",enabled:true,src:\"any\",dst:\"any\",dport:53,dport_end:53,sport:0,state:0,log:false,hits:2,comment:\"wan dns blocked\"},\n"
    "  {id:6,action:\"deny\",protocol:\"tcp\",dir:\"in\",enabled:true,src:\"any\",dst:\"any\",dport:69,dport_end:69,sport:0,state:0,log:true,hits:1,comment:\"wan console blocked\"}],\n"
    "  services:[{proto:\"udp\",port:67},{proto:\"udp\",port:53},{proto:\"tcp\",port:69},{proto:\"tcp\",port:8080}],\n"
    "  counters:{in_allow:2034,in_drop:9,out_allow:2077,out_drop:0,fwd_allow:1842,fwd_drop:6,rate_drops:0}},\n"
    " log:[\"5120s in drop tcp 198.51.100.7:44120->10.0.2.15:23 rule=6\",\"5102s fwd drop udp 192.168.10.105:53001->203.0.113.9:9999 rule=policy\",\"4980s in drop tcp 203.0.113.44:55210->10.0.2.15:22 rule=policy\"]};\n"
    "\n"
    "let DATA=null,DEMO_MODE=false;\n"
    "const $=id=>document.getElementById(id);\n"
    "const val=id=>$(id).value.trim();\n"
    "const esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n"
    "const num=n=>Number(n||0).toLocaleString('en-US');\n"
    "function token(){try{return sessionStorage.getItem('sharkos-token')||''}catch(e){return $('token').value}}\n"
    "function saveToken(){try{sessionStorage.setItem('sharkos-token',$('token').value.trim())}catch(e){}}\n"
    "function setTokenInput(){try{$('token').value=sessionStorage.getItem('sharkos-token')||''}catch(e){}}\n"
    "const hdr=()=>({'Content-Type':'text/plain','X-Shark-Token':token()});\n"
    "function kv(rows){return rows.map(r=>`<div class=\"kv\"><span>${esc(r[0])}</span><b class=\"${r[2]?'plain':''}\">${r[1]}</b></div>`).join('')}\n"
    "function stat(rows){return rows.map(r=>`<div class=\"stat\"><span>${esc(r[0])}</span><b style=\"font-family:var(--mono)\">${r[1]}</b></div>`).join('')}\n"
    "function table(cols,rows,empty){if(!rows||!rows.length)return `<div class=\"empty\">${empty||'No entries'}</div>`;\n"
    " return `<table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`}\n"
    "function tag(text,kind){return `<span class=\"tag ${kind||'gray'}\">${esc(text)}</span>`}\n"
    "function onoff(v,yes,no){return tag(v?(yes||'up'):(no||'down'),v?'ok':'bad')}\n"
    "function dur(s){s=Number(s||0);if(s<60)return s+' s';if(s<3600)return Math.floor(s/60)+' m '+s%60+' s';return Math.floor(s/3600)+' h '+Math.floor(s%3600/60)+' m'}\n"
    "\n"
    "function render(d){\n"
    " DATA=d;\n"
    " const IF=d.interfaces||null,lan=d.lan||{},dhcp=lan.dhcp||{},wan=d.wan||{},dns=d.dns||{},fw=d.firewall||{},nat=d.nat||{},s=d.stats||{},http=d.http||{};\n"
    " $('statePill').className='pill '+(d.running?'on':'off');$('statePill').textContent=d.running?'running':'stopped';\n"
    " $('demoPill').style.display=DEMO_MODE?'inline-block':'none';$('demoBanner').classList.toggle('show',DEMO_MODE);\n"
    " $('topMeta').textContent='port '+http.port+' \u00b7 uptime '+dur(d.uptime);\n"
    " $('crumbMode').textContent=IF?(IF.mode==='dedicated'?'dedicated uplink + LAN':'single-NIC shared mode'):'interfaces unavailable';\n"
    " $('crumbUp').textContent=(d.product||'SharkOS Router')+' \u00b7 '+(IF?IF.count+' adapter(s) detected':'')+' \u00b7 router up '+dur(d.router_uptime);\n"
    "\n"
    " /* System */\n"
    " $('system').innerHTML=kv([\n"
    "  ['Hostname','SharkOS Router',1],['Product',d.product||'SharkOS Server',1],\n"
    "  ['Router state',d.running?tag('running','ok'):tag('stopped','bad')],\n"
    "  ['System uptime',dur(d.uptime)],['Router uptime',dur(d.router_uptime)],\n"
    "  ['Management',`http://${lan.ip||'\u2014'}:${http.port}/`],\n"
    "  ['Web server',onoff(http.running,'up','down')],\n"
    "  ['API authentication',http.auth?tag('token required','warn'):tag('none','bad')],\n"
    "  ['HTTP requests',num(s.http_requests)],\n"
    "  ['Detected adapters',IF?IF.count:'\u2014']]);\n"
    "\n"
    " /* Interfaces \u2014 pfSense style assignments table */\n"
    " $('ifMode').textContent=IF?(IF.count+' detected \u00b7 '+(IF.mode==='dedicated'?'dedicated':'shared')):'\u2014';\n"
    " if(IF&&IF.ports&&IF.ports.length){\n"
    "  $('ifTable').innerHTML=table(['Interface','Role','Adapter','MAC','Address','Status'],\n"
    "   IF.ports.map((p,i)=>{\n"
    "    const role=p.role||(i===IF.wan?'wan':(!IF.lan_shared&&i===IF.lan)?'lan':'unused');\n"
    "    const address=role==='wan'?(wan.ip||'\u2014'):role==='lan'?((lan.ip||'\u2014')+' / '+(lan.mask||'\u2014')):'\u2014';\n"
    "    const status=role==='unused'?'\u2014':(p.link?tag('up','ok'):(p.active?tag('down','bad'):tag('assigned','warn')));\n"
    "    return [esc(p.ifname),role==='wan'?tag('WAN \u00b7 uplink','ok'):role==='lan'?tag('LAN','gray'):tag('unused','gray'),\n"
    "            esc(p.driver),esc(p.mac||'unknown'),esc(address),status];\n"
    "   }),'No adapters detected');\n"
    "  $('ifNote').innerHTML=IF.lan_shared\n"
    "   ? 'Only one NIC is present, so <b>WAN (uplink) and LAN share the same adapter</b>. Plug a second NIC in and the router assigns it as a dedicated LAN port automatically (<b>rtr port auto</b>).'\n"
    "   : 'Auto-assigned: <b>'+esc((IF.uplink||{}).ifname||'NIC 0')+'</b> is the uplink (WAN) adapter and <b>'+esc((IF.lan_port||{}).ifname||'NIC 1')+'</b> is the LAN port. Change it with <b>rtr port wan|lan &lt;index&gt;</b>.';\n"
    " }else{\n"
    "  $('ifTable').innerHTML=table(['Interface','Role','Adapter','Address','Status'],\n"
    "   [[esc('uplink'),tag('WAN \u00b7 uplink','ok'),esc((wan.driver)||'primary NIC'),esc(wan.ip||'\u2014'),onoff(wan.link)],\n"
    "    [esc('lan'),tag('LAN','gray'),esc('shared adapter'),esc((lan.ip||'\u2014')+' / '+(lan.mask||'\u2014')),onoff(dhcp.enabled,'on','off')]],'No interfaces');\n"
    "  $('ifNote').textContent='This build does not report an adapter inventory; WAN and LAN share the primary NIC.';\n"
    " }\n"
    " $('wanName').textContent=IF&&IF.uplink?(IF.uplink.ifname+' \u00b7 '+IF.uplink.driver):'uplink adapter';\n"
    " $('lanName').textContent=IF&&!IF.lan_shared&&IF.lan_port?IF.lan_port.ifname:'shared / LAN';\n"
    "\n"
    " /* WAN */\n"
    " $('wan').innerHTML=kv([\n"
    "  ['Adapter',IF&&IF.uplink?esc(IF.uplink.ifname)+' \u00b7 '+esc(IF.uplink.driver):'primary NIC',1],\n"
    "  ['MAC',IF&&IF.uplink?esc(IF.uplink.mac):'\u2014'],\n"
    "  ['PCI slot',IF&&IF.uplink?esc(IF.uplink.pci):'\u2014'],\n"
    "  ['Mode',tag(wan.mode||'\u2014','gray')],['Status',esc(wan.status||'\u2014'),1],\n"
    "  ['IP address',esc(wan.ip||'\u2014')],['Subnet mask',esc(wan.mask||'\u2014')],\n"
    "  ['Gateway',esc(wan.gw||'\u2014')],['Upstream DNS',esc(wan.dns||'\u2014')],\n"
    "  ['DHCP client',esc(wan.dhcp_state||'\u2014'),1],['Lease remaining',dur(wan.lease_left)],\n"
    "  ['Link',onoff(wan.link,'up','down')]]);\n"
    "\n"
    " /* LAN / DHCP */\n"
    " $('lan').innerHTML=kv([\n"
    "  ['Interface',IF&&!IF.lan_shared&&IF.lan_port?esc(IF.lan_port.ifname):'shared with uplink',1],\n"
    "  ['IPv4 address',esc(lan.ip||'\u2014')],['Subnet mask',esc(lan.mask||'\u2014')],\n"
    "  ['DHCP server',onoff(dhcp.enabled,'enabled','disabled')],\n"
    "  ['Pool',esc((dhcp.pool_start||'\u2014')+' \u2192 '+(dhcp.pool_end||'\u2014'))],\n"
    "  ['Lease time',dur(dhcp.lease)],['Active leases',num((dhcp.leases||[]).length)],\n"
    "  ['Reservations',num((dhcp.reservations||[]).length)],\n"
    "  ['Clients gateway',esc(lan.ip||'\u2014')]]);\n"
    "\n"
    " /* Leases */\n"
    " $('leaseCount').textContent=(dhcp.leases||[]).length+' lease(s) \u00b7 '+(dhcp.reservations||[]).length+' reservation(s)';\n"
    " $('leases').innerHTML=table(['IP','MAC','Host','State','Expires'],(dhcp.leases||[]).map(l=>\n"
    "  [esc(l.ip),esc(l.mac),esc(l.host||'\u2014'),l.bound?tag('bound','ok'):tag('offered','warn'),dur(l.expires)]),'No DHCP leases yet');\n"
    " $('reservations').innerHTML=table(['#','MAC','IP','Host',''],(dhcp.reservations||[]).map(r=>\n"
    "  [r.id,esc(r.mac),esc(r.ip),esc(r.host||'\u2014'),`<button class=\"btn sm danger\" onclick=\"run('rtr dhcp unreserve ${r.id}')\">remove</button>`]),'No static reservations');\n"
    "\n"
    " /* DNS */\n"
    " $('dnsDomain').textContent='.'+(dns.domain||'lan');\n"
    " $('dns').innerHTML=kv([\n"
    "  ['Resolver',onoff(dns.enabled,'enabled','disabled')],\n"
    "  ['Upstream',esc(dns.upstream||'\u2014')],['Secondary',esc(dns.secondary||'\u2014')],\n"
    "  ['Local domain',esc(dns.domain||'\u2014')],\n"
    "  ['Queries',num(s.dns_queries)],['Answered locally',num(s.dns_local)],\n"
    "  ['Forwarded',num(s.dns_forwarded)],['Cache hits',num(s.dns_cached)],\n"
    "  ['Failures',num(s.dns_failed)]]);\n"
    " const rec=(dns.records||[]).map(r=>[esc(r.name),esc(r.ip),r.local?tag('static','ok'):tag('cached','gray')]);\n"
    " $('dns').innerHTML+=`<div style=\"font-size:11px;color:var(--muted);margin:12px 0 6px;text-transform:uppercase;letter-spacing:.6px\">Records &amp; cache</div>`+\n"
    "  table(['Name','Address','Type'],rec,'No DNS records');\n"
    "\n"
    " /* Firewall */\n"
    " const c=fw.counters||{};\n"
    " $('fwSummary').textContent=(fw.rules||[]).length+' rules \u00b7 '+(fw.services||[]).length+' services';\n"
    " $('fwPolicies').innerHTML=kv([\n"
    "  ['Input policy',tag(fw.in||'\u2014',fw.in==='allow'?'ok':'bad')],\n"
    "  ['Output policy',tag(fw.out||'\u2014',fw.out==='allow'?'ok':'bad')],\n"
    "  ['Forward policy',tag(fw.forward||'\u2014',fw.forward==='allow'?'ok':'bad')],\n"
    "  ['Rate limit',fw.rate?num(fw.rate)+' pps/src':'off'],\n"
    "  ['Rules',num((fw.rules||[]).length)+' / 64']]);\n"
    " $('fwCounters').innerHTML=stat([\n"
    "  ['IN allow / drop',num(c.in_allow)+' / '+num(c.in_drop)],\n"
    "  ['OUT allow / drop',num(c.out_allow)+' / '+num(c.out_drop)],\n"
    "  ['FWD allow / drop',num(c.fwd_allow)+' / '+num(c.fwd_drop)],\n"
    "  ['Rate drops',num(c.rate_drops)],\n"
    "  ['Dropped frames',num(s.dropped_frames)]]);\n"
    " $('fwRules').innerHTML=table(['#','Act','Proto','Dir','Source','Dest','DPort','State','Hits','Comment',''],\n"
    "  (fw.rules||[]).map(r=>[r.id,tag(r.action,r.action==='allow'?'ok':'bad'),esc(r.protocol),esc(r.dir),esc(r.src),esc(r.dst),\n"
    "   r.dport?(r.dport+(r.dport_end&&r.dport_end!==r.dport?'\u2013'+r.dport_end:'')):'any',\n"
    "   r.state===1?'new':r.state===2?'est.':'any',num(r.hits),esc(r.comment||''),\n"
    "   `<button class=\"btn sm\" onclick=\"run('fw move ${r.id} up')\">\u2191</button> <button class=\"btn sm\" onclick=\"run('fw ${r.enabled?'disable':'enable'} ${r.id}')\">${r.enabled?'off':'on'}</button> <button class=\"btn sm danger\" onclick=\"run('fw delete ${r.id}')\">\u2715</button>`]),'No rules \u2014 default policy applies');\n"
    " $('fwServices').innerHTML=table(['Protocol','Port','Purpose'],\n"
    "  (fw.services||[]).map(x=>{const p=Number(x.port);return [esc(x.proto),p,p===67?'DHCP server':p===53?'DNS':(http.port&&p===http.port)?'management console':'port forward']}),'No service ports');\n"
    "\n"
    " /* NAT */\n"
    " $('natState').textContent=nat.enabled?'enabled':'disabled';\n"
    " $('forwards').innerHTML=table(['#','Proto','WAN','LAN target','Hits','Comment',''],(nat.forwards||[]).map(f=>\n"
    "  [f.id,esc(f.proto),f.wan_port,esc(f.lan_ip)+':'+f.lan_port,num(f.hits),esc(f.comment||''),\n"
    "   `<button class=\"btn sm danger\" onclick=\"run('rtr forward del ${f.id}')\">remove</button>`]),'No port forwards');\n"
    " $('mappings').innerHTML=table(['Proto','LAN source','WAN port','Remote','Packets'],(nat.mappings||[]).map(m=>\n"
    "  [m.proto===6?'tcp':m.proto===17?'udp':'icmp',esc(m.lan_ip)+':'+m.lan_port,m.wan_port,esc(m.remote_ip),num(m.packets)]),'No active NAT mappings');\n"
    "\n"
    " /* Traffic */\n"
    " $('traffic').innerHTML=stat([\n"
    "  ['DHCP discover / offer',num(s.dhcp_discover)+' / '+num(s.dhcp_offer)],\n"
    "  ['DHCP request / ack',num(s.dhcp_request)+' / '+num(s.dhcp_ack)],\n"
    "  ['DHCP NAK',num(s.dhcp_nak)],\n"
    "  ['DNS queries',num(s.dns_queries)],\n"
    "  ['DNS local / forwarded',num(s.dns_local)+' / '+num(s.dns_forwarded)],\n"
    "  ['DNS cached / failed',num(s.dns_cached)+' / '+num(s.dns_failed)],\n"
    "  ['NAT mappings created',num(s.nat_mappings)],\n"
    "  ['Forwarded frames',num(s.forwarded_frames)],\n"
    "  ['Dropped frames',num(s.dropped_frames)],\n"
    "  ['HTTP requests',num(s.http_requests)]]);\n"
    "\n"
    " /* Log */\n"
    " $('logBox').textContent=(d.log||[]).length?(d.log||[]).join('\\n'):'No drops logged.';\n"
    "\n"
    " /* Pre-fill quick configure */\n"
    " $('lanIp').value=lan.ip||'';$('lanMask').value=lan.mask||'';\n"
    " $('poolStart').value=dhcp.pool_start||'';$('poolEnd').value=dhcp.pool_end||'';$('leaseSecs').value=dhcp.lease||'';\n"
    " $('dns1').value=dns.upstream||'';$('dns2').value=dns.secondary||'';$('dnsDomainIn').value=dns.domain||'';\n"
    " $('httpPort').value=http.port||'';\n"
    "}\n"
    "\n"
    "async function refresh(){\n"
    " try{\n"
    "  const r=await fetch('/api/status',{headers:{'X-Shark-Token':token()}});\n"
    "  if(!r.ok)throw 0;\n"
    "  const d=await r.json();DEMO_MODE=false;render(d);\n"
    " }catch(e){DEMO_MODE=true;render(DEMO);}\n"
    "}\n"
    "async function run(cmd){\n"
    " if(!cmd)return;\n"
    " const out=$('consoleOut');out.textContent='$ '+cmd+'\\n\u2026';\n"
    " if(DEMO_MODE){out.textContent='$ '+cmd+'\\n(demo mode: no live router connected)\\n\\nStart the router with  rtr start 69  on the SharkOS Server console, then enter the API token above and click Connect.';return;}\n"
    " try{\n"
    "  const r=await fetch('/api/cli',{method:'POST',headers:hdr(),body:cmd});\n"
    "  const text=await r.text();let output=text;\n"
    "  try{const j=JSON.parse(text);output=j.output||j.error||text}catch(e){}\n"
    "  out.textContent='$ '+cmd+'\\n'+output;\n"
    "  if(r.ok)await refresh();\n"
    " }catch(e){out.textContent='$ '+cmd+'\\nRequest failed: '+e}\n"
    "}\n"
    "function lanSave(){run(`rtr lan ${val('lanIp')} ${val('lanMask')}`)}\n"
    "function poolSave(){run(`rtr dhcp pool ${val('poolStart')} ${val('poolEnd')}`);run(`rtr dhcp lease ${val('leaseSecs')}`)}\n"
    "function dnsSave(){run(`rtr dns upstream ${val('dns1')} ${val('dns2')}`);run(`rtr dns domain ${val('dnsDomainIn')}`)}\n"
    "function wanStatic(){run(`rtr wan static ${val('wanIp')} ${val('wanMask')} ${val('wanGw')} ${val('wanDns')}`)}\n"
    "function fwdAdd(){run(`rtr forward add ${val('fProto')} ${val('fWan')} ${val('fLanIp')} ${val('fLanPort')} ${val('fComment')}`)}\n"
    "function ruleAdd(){let c=`fw add ${val('rAct')} ${val('rProto')} dir ${val('rDir')}`;if(val('rSrc'))c+=' from '+val('rSrc');if(val('rPort'))c+=' dport '+val('rPort');run(c)}\n"
    "setTokenInput();refresh();\n"
    "setInterval(()=>{\n"
    " const t=document.activeElement?document.activeElement.tagName:'';\n"
    " if(!DEMO_MODE && t!=='INPUT' && t!=='SELECT' && t!=='TEXTAREA')refresh();\n"
    "},10000);\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";

static const unsigned int ROUTER_UI_HTML_LEN = sizeof(ROUTER_UI_HTML) - 1;

#endif
